'use client'
import {
  cn,
  useControllableSignal,
  useRovingFocus,
  useSignal,
  useSignalEffect,
  useSignals,
} from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { useId, useRef } from 'react'
import { clamp, formatColor, hsvToRgb, parseColor, sameColor, toHex } from './color'
import type { ColorFormat, Hsv } from './color'
import styles from './color-picker.module.css'

export type { ColorFormat } from './color'

export interface ColorPickerLabels {
  hue?: string
  /** Accessible name for the alpha slider. */
  alpha?: string
  colorArea?: string
  saturation?: string
  brightness?: string
  eyedropper?: string
  presets?: string
  hex?: string
}

export interface ColorPickerProps {
  /**
   * Wired automatically by a wrapping `Field` — its label id. Forwarded to the text input so
   * the Field's label names it; the built-in fallback name is then not applied.
   */
  'aria-labelledby'?: string
  /**
   * Wired automatically by a wrapping `Field` — the ids of its hint/error text. Forwarded to
   * the text input so the supporting text is announced, not just displayed.
   */
  'aria-describedby'?: string
  /** Wired automatically by a wrapping `Field` when it is in an error state. */
  'aria-invalid'?: boolean
  /** Id for the focusable text input. `Field` supplies this automatically. */
  id?: string
  value?: string
  /**
   * The initial value when uncontrolled.
   *
   * @defaultValue `#3b82f6`
   * @see the component manifest
   */
  defaultValue?: string
  onValueChange?: (value: string) => void
  presets?: string[]
  /**
   * When true, enables alpha (opacity) selection.
   *
   * @defaultValue `true`
   * @see the component manifest
   */
  alpha?: boolean
  /**
   * Notation for the emitted value. Alpha is included whenever `alpha` is on, so the width
   * of the emitted string is stable.
   *
   * @defaultValue `'hex'`
   * @see the component manifest
   */
  format?: ColorFormat
  label?: string
  /**
   * Invisible accessible name, for when a visible element outside this component already
   * labels it and `label` would render that text a second time.
   *
   * `label` on this component is **visible**. `IconButton.label` and `Sparkline.label` are
   * invisible names, so an adopter arriving with that prior writes `label` here and gets the
   * text twice (2026-08-22 report item 13). Both props are listed side by side, each saying
   * which it is.
   */
  ariaLabel?: string
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  /** Submitted with a surrounding form — a hidden input carrying the current value. */
  name?: string
  size?: 'sm' | 'md' | 'lg'
  className?: string
  labels?: ColorPickerLabels
}

interface EyeDropperResult {
  sRGBHex: string
}
interface EyeDropperCtor {
  new (): { open: () => Promise<EyeDropperResult> }
}

const DEFAULT_COLOR = '#3b82f6'

export function ColorPicker({
  id,
  value,
  defaultValue,
  onValueChange,
  presets,
  alpha = true,
  format = 'hex',
  label,
  ariaLabel,
  disabled = false,
  name,
  size = 'md',
  className,
  labels,
  'aria-labelledby': ariaLabelledBy,
  'aria-describedby': ariaDescribedBy,
  'aria-invalid': ariaInvalid,
}: ColorPickerProps) {
  useSignals()
  const baseId = useId()
  const inputId = id ?? `${baseId}-hex`
  const areaRef = useRef<HTMLDivElement>(null)
  const dragging = useSignal(false)

  const [color, setColor] = useControllableSignal<string>({
    value,
    defaultValue: defaultValue ?? DEFAULT_COLOR,
    onChange: onValueChange,
  })

  /**
   * HSV is the stored state, not hex. Hex is 8-bit, so hue→hex→hue loses precision on every
   * nudge and repeated arrow presses bleed saturation away. The prop only re-seeds this when
   * it names a different colour, so the component's own edits are never round-tripped.
   */
  const hsv = useSignal<Hsv>(parseColor(color.peek()) ?? { h: 217, s: 76, v: 96, a: 1 })
  const lastEmitted = useRef<string>(color.peek())
  const current = color.value
  if (current !== lastEmitted.current && !sameColor(current, lastEmitted.current)) {
    const parsed = parseColor(current)
    if (parsed) hsv.value = parsed
    lastEmitted.current = current
  }

  const hsvValue = hsv.value
  const swatch = formatColor(hsvValue, format, alpha)
  const opaqueHex = toHex(hsvToRgb({ ...hsvValue, a: 1 }), false)
  const hueHex = toHex(hsvToRgb({ h: hsvValue.h, s: 100, v: 100, a: 1 }), false)

  const resolved = {
    hue: labels?.hue ?? t(builtin.colorPicker.hue),
    alpha: labels?.alpha ?? t(builtin.colorPicker.alpha),
    colorArea: labels?.colorArea ?? t(builtin.colorPicker.colorArea),
    saturation: labels?.saturation ?? t(builtin.colorPicker.saturation),
    brightness: labels?.brightness ?? t(builtin.colorPicker.brightness),
    eyedropper: labels?.eyedropper ?? t(builtin.colorPicker.eyedropper),
    presets: labels?.presets ?? t(builtin.colorPicker.presets),
    hex: labels?.hex ?? t(builtin.colorPicker.hex),
  }

  function commit(next: Hsv): void {
    hsv.value = next
    const out = formatColor(next, format, alpha)
    lastEmitted.current = out
    setColor(out)
  }

  function setFromPointer(clientX: number, clientY: number): void {
    const el = areaRef.current
    if (!el) return
    const rect = el.getBoundingClientRect()
    if (rect.width === 0 || rect.height === 0) return
    const sx = clamp((clientX - rect.left) / rect.width, 0, 1)
    const sy = clamp((clientY - rect.top) / rect.height, 0, 1)
    // x is saturation, y is value — matching the gradient the area actually paints.
    commit({ ...hsv.peek(), s: sx * 100, v: (1 - sy) * 100 })
  }

  useSignalEffect(() => {
    if (!dragging.value) return
    const onMove = (e: PointerEvent): void => setFromPointer(e.clientX, e.clientY)
    const onUp = (): void => {
      dragging.value = false
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    return () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }
  })

  /**
   * Read on the client only. Reading `window.EyeDropper` during render made the server emit
   * no button and the first client render emit one, which is a hydration mismatch on a
   * component that is server-rendered despite `clientJs: 'required'`.
   */
  const hasEyeDropper = useSignal(false)
  useSignalEffect(() => {
    hasEyeDropper.value =
      typeof window !== 'undefined' &&
      typeof (window as unknown as { EyeDropper?: EyeDropperCtor }).EyeDropper === 'function'
  })

  async function pickFromScreen(): Promise<void> {
    const ctor = (window as unknown as { EyeDropper?: EyeDropperCtor }).EyeDropper
    if (!ctor) return
    try {
      const result = await new ctor().open()
      const parsed = parseColor(result.sRGBHex)
      if (parsed) commit({ ...parsed, a: hsv.peek().a })
    } catch {
      // The user dismissed the picker; nothing to do.
    }
  }

  // The hex field keeps its own draft so a half-typed value never reaches onValueChange.
  // The old build called setColor on every keystroke, and an unparseable prefix fell back to
  // black, so the area and thumb thrashed while the user typed.
  const draft = useSignal<string | null>(null)
  const hexText = draft.value ?? (format === 'hex' ? swatch : toHex(hsvToRgb(hsvValue), alpha))

  function commitDraft(): void {
    const text = draft.peek()
    draft.value = null
    if (text === null) return
    const parsed = parseColor(text)
    if (parsed) commit(alpha ? parsed : { ...parsed, a: 1 })
  }

  const presetList = presets ?? []
  const roving = useRovingFocus({ orientation: 'horizontal', loop: true })

  return (
    <div
      className={cn(styles['wrapper'], className)}
      data-size={size}
      data-disabled={disabled || undefined}
    >
      {label && (
        <label className={styles['label']} htmlFor={inputId}>
          {label}
        </label>
      )}

      {/* Two real range inputs carry the slider semantics for the two axes. A single
          role="slider" cannot describe a 2-D area — the old one had no aria-valuenow at all,
          which is an invalid slider — and the native inputs bring Home/End/PageUp/PageDown
          and arrow stepping with them instead of a hand-rolled key switch. */}
      <div
        ref={areaRef}
        role="group"
        aria-label={resolved.colorArea}
        className={styles['area']}
        style={{ background: hueHex }}
        onPointerDown={(e) => {
          if (disabled) return
          e.preventDefault()
          dragging.value = true
          setFromPointer(e.clientX, e.clientY)
        }}
      >
        <input
          type="range"
          className={styles['axis']}
          aria-label={resolved.saturation}
          min={0}
          max={100}
          step={1}
          value={Math.round(hsvValue.s)}
          disabled={disabled}
          aria-valuetext={`${Math.round(hsvValue.s)}%`}
          onChange={(e) => commit({ ...hsv.peek(), s: Number(e.currentTarget.value) })}
        />
        <input
          type="range"
          className={styles['axis']}
          aria-label={resolved.brightness}
          min={0}
          max={100}
          step={1}
          value={Math.round(hsvValue.v)}
          disabled={disabled}
          aria-valuetext={`${Math.round(hsvValue.v)}%`}
          onChange={(e) => commit({ ...hsv.peek(), v: Number(e.currentTarget.value) })}
        />
        <span
          className={styles['thumb']}
          style={{
            insetInlineStart: `${hsvValue.s}%`,
            insetBlockStart: `${100 - hsvValue.v}%`,
            backgroundColor: opaqueHex,
          }}
          aria-hidden="true"
        />
      </div>

      <div className={styles['sliders']}>
        <input
          type="range"
          className={cn(styles['slider'], styles['hue'])}
          aria-label={resolved.hue}
          min={0}
          max={360}
          step={1}
          value={Math.round(hsvValue.h)}
          disabled={disabled}
          onChange={(e) => commit({ ...hsv.peek(), h: Number(e.currentTarget.value) })}
        />
        {alpha && (
          <input
            type="range"
            className={cn(styles['slider'], styles['alpha'])}
            aria-label={resolved.alpha}
            min={0}
            max={100}
            step={1}
            value={Math.round(hsvValue.a * 100)}
            disabled={disabled}
            aria-valuetext={`${Math.round(hsvValue.a * 100)}%`}
            style={{ '--cascivo-color-picker-alpha-to': opaqueHex } as React.CSSProperties}
            onChange={(e) => commit({ ...hsv.peek(), a: Number(e.currentTarget.value) / 100 })}
          />
        )}
      </div>

      <div className={styles['row']}>
        <span
          className={styles['preview']}
          style={{ backgroundColor: swatch }}
          aria-hidden="true"
        />
        <input
          id={inputId}
          type="text"
          className={styles['hex']}
          value={hexText}
          disabled={disabled}
          autoComplete="off"
          // aria-labelledby from a Field outranks a name of our own; only fall back when the
          // Field has not supplied one.
          aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? resolved.hex)}
          aria-labelledby={ariaLabelledBy}
          aria-describedby={ariaDescribedBy}
          aria-invalid={ariaInvalid}
          onChange={(e) => {
            draft.value = e.currentTarget.value
          }}
          onBlur={commitDraft}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              e.preventDefault()
              commitDraft()
            } else if (e.key === 'Escape') {
              draft.value = null
            }
          }}
        />
        {hasEyeDropper.value && (
          <button
            type="button"
            className={styles['eyedropper']}
            aria-label={resolved.eyedropper}
            disabled={disabled}
            onClick={() => void pickFromScreen()}
          >
            <span className={styles['eyedropperGlyph']} aria-hidden="true" />
          </button>
        )}
      </div>

      {presetList.length > 0 && (
        <div role="group" aria-label={resolved.presets} className={styles['presets']}>
          {presetList.map((preset, i) => {
            const itemProps = roving.getItemProps(i)
            const selected = sameColor(preset, swatch)
            return (
              <button
                key={preset}
                ref={itemProps.ref as (el: HTMLButtonElement | null) => void}
                type="button"
                className={styles['preset']}
                style={{ backgroundColor: preset }}
                aria-label={preset}
                aria-pressed={selected}
                disabled={disabled}
                // Arrows move focus between swatches; they used to change the value instead,
                // which is the inverse of what a group of buttons should do.
                tabIndex={itemProps.tabIndex}
                onKeyDown={itemProps.onKeyDown}
                onFocus={itemProps.onFocus}
                onClick={() => {
                  const parsed = parseColor(preset)
                  if (parsed) commit(alpha ? parsed : { ...parsed, a: 1 })
                }}
              />
            )
          })}
        </div>
      )}

      {name !== undefined && <input type="hidden" name={name} value={swatch} />}

      {/* Mounted unconditionally so the first change is announced too. */}
      <span className={styles['srOnly']} role="status" aria-live="polite">
        {t(builtin.colorPicker.value, { color: swatch })}
      </span>
    </div>
  )
}

/**
 * Colour conversion and parsing, kept pure so every edge — 3/4/6/8-digit hex, the NaN
 * fallback, round-trip fidelity — is unit-testable without a DOM.
 *
 * The picking area is **HSV**, not HSL. The area's gradient is the classic
 * `linear-gradient(to top, #000, transparent)` over `linear-gradient(to right, #fff,
 * transparent)` on a pure-hue ground, which paints saturation on x and *value* on y. The
 * previous build mapped y to HSL lightness against that same gradient, so the two disagreed:
 * clicking the visibly pure hue at the top-right returned `hsl(h, 100%, 100%)` — white — and
 * the thumb for `#ff0000` sat halfway down the area rather than on the colour it names.
 *
 * HSVA is also what the component stores between edits. Hex is 8-bit, so hue→hex→hue loses
 * precision on every nudge; keeping HSVA and deriving hex on the way out means dragging the
 * hue slider no longer bleeds saturation away.
 */

export interface Rgb {
  r: number
  g: number
  b: number
  a: number
}

/** Hue 0–360, saturation and value 0–100, alpha 0–1. */
export interface Hsv {
  h: number
  s: number
  v: number
  a: number
}

export function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

/** Parse 3-, 4-, 6- and 8-digit hex, with or without `#`. Unparseable input returns null. */
export function parseHex(hex: string): Rgb | null {
  const h = hex.trim().replace(/^#/, '')
  if (!/^(?:[0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/.test(h)) return null
  const expand = (s: string): string =>
    s.length <= 4
      ? s
          .split('')
          .map((c) => c + c)
          .join('')
      : s
  const full = expand(h)
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
    a: full.length >= 8 ? parseInt(full.slice(6, 8), 16) / 255 : 1,
  }
}

/**
 * Hex string for `rgb`. `withAlpha` forces the 8-digit form even at full opacity, so a caller
 * that has enabled alpha always receives a fixed width — the old build silently dropped the
 * alpha pair whenever `a >= 1`, flipping the output between 7 and 9 characters.
 */
export function toHex({ r, g, b, a }: Rgb, withAlpha: boolean): string {
  const part = (n: number): string => clamp(Math.round(n), 0, 255).toString(16).padStart(2, '0')
  const base = `#${part(r)}${part(g)}${part(b)}`
  return withAlpha ? base + part(a * 255) : base
}

/** `rgb(r g b)` / `rgb(r g b / a)` in the modern space-separated form. */
export function toRgbString({ r, g, b, a }: Rgb, withAlpha: boolean): string {
  const n = (x: number): number => clamp(Math.round(x), 0, 255)
  const body = `${n(r)} ${n(g)} ${n(b)}`
  return withAlpha ? `rgb(${body} / ${round(a, 2)})` : `rgb(${body})`
}

/** `hsl(h s% l%)` / `hsl(h s% l% / a)`, converted from HSV. */
export function toHslString(hsv: Hsv, withAlpha: boolean): string {
  const { h, s, l } = hsvToHsl(hsv)
  const body = `${Math.round(h)} ${Math.round(s)}% ${Math.round(l)}%`
  return withAlpha ? `hsl(${body} / ${round(hsv.a, 2)})` : `hsl(${body})`
}

function round(n: number, places: number): number {
  const f = 10 ** places
  return Math.round(n * f) / f
}

export function rgbToHsv({ r, g, b, a }: Rgb): Hsv {
  const rn = r / 255
  const gn = g / 255
  const bn = b / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const d = max - min
  let h = 0
  if (d !== 0) {
    if (max === rn) h = ((gn - bn) / d) % 6
    else if (max === gn) h = (bn - rn) / d + 2
    else h = (rn - gn) / d + 4
    h *= 60
    if (h < 0) h += 360
  }
  return { h, s: max === 0 ? 0 : (d / max) * 100, v: max * 100, a }
}

export function hsvToRgb({ h, s, v, a }: Hsv): Rgb {
  const sn = clamp(s, 0, 100) / 100
  const vn = clamp(v, 0, 100) / 100
  const hn = ((h % 360) + 360) % 360
  const c = vn * sn
  const x = c * (1 - Math.abs(((hn / 60) % 2) - 1))
  const m = vn - c
  let rn = 0
  let gn = 0
  let bn = 0
  if (hn < 60) [rn, gn, bn] = [c, x, 0]
  else if (hn < 120) [rn, gn, bn] = [x, c, 0]
  else if (hn < 180) [rn, gn, bn] = [0, c, x]
  else if (hn < 240) [rn, gn, bn] = [0, x, c]
  else if (hn < 300) [rn, gn, bn] = [x, 0, c]
  else [rn, gn, bn] = [c, 0, x]
  return { r: (rn + m) * 255, g: (gn + m) * 255, b: (bn + m) * 255, a }
}

/** HSV → HSL, for the `hsl()` output format. */
export function hsvToHsl({ h, s, v, a }: Hsv): { h: number; s: number; l: number; a: number } {
  const sn = clamp(s, 0, 100) / 100
  const vn = clamp(v, 0, 100) / 100
  const l = vn * (1 - sn / 2)
  const sl = l === 0 || l === 1 ? 0 : (vn - l) / Math.min(l, 1 - l)
  return { h, s: sl * 100, l: l * 100, a }
}

/** The output formats an adopter can ask for. */
export type ColorFormat = 'hex' | 'rgb' | 'hsl'

/** Serialise `hsv` in `format`, including alpha only when the component enables it. */
export function formatColor(hsv: Hsv, format: ColorFormat, withAlpha: boolean): string {
  if (format === 'rgb') return toRgbString(hsvToRgb(hsv), withAlpha)
  if (format === 'hsl') return toHslString(hsv, withAlpha)
  return toHex(hsvToRgb(hsv), withAlpha)
}

/**
 * Parse any of the three output formats back to HSV, so a controlled `value` round-trips
 * whatever the component last emitted. Returns null on anything unrecognised.
 */
export function parseColor(value: string): Hsv | null {
  const text = value.trim()
  const rgbMatch =
    /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:\s*[/,]\s*([\d.%]+))?\s*\)$/i.exec(text)
  if (rgbMatch) {
    return rgbToHsv({
      r: Number(rgbMatch[1]),
      g: Number(rgbMatch[2]),
      b: Number(rgbMatch[3]),
      a: parseAlpha(rgbMatch[4]),
    })
  }
  const hslMatch =
    /^hsla?\(\s*([\d.]+)(?:deg)?[\s,]+([\d.]+)%[\s,]+([\d.]+)%(?:\s*[/,]\s*([\d.%]+))?\s*\)$/i.exec(
      text,
    )
  if (hslMatch) {
    return hslToHsv(
      Number(hslMatch[1]),
      Number(hslMatch[2]),
      Number(hslMatch[3]),
      parseAlpha(hslMatch[4]),
    )
  }
  const rgb = parseHex(text)
  return rgb ? rgbToHsv(rgb) : null
}

function parseAlpha(raw: string | undefined): number {
  if (raw === undefined) return 1
  const n = raw.endsWith('%') ? Number(raw.slice(0, -1)) / 100 : Number(raw)
  return Number.isNaN(n) ? 1 : clamp(n, 0, 1)
}

function hslToHsv(h: number, s: number, l: number, a: number): Hsv {
  const sn = clamp(s, 0, 100) / 100
  const ln = clamp(l, 0, 100) / 100
  const v = ln + sn * Math.min(ln, 1 - ln)
  return { h, s: v === 0 ? 0 : 2 * (1 - ln / v) * 100, v: v * 100, a }
}

/** True when both colours resolve to the same 8-bit RGBA, so `#FFF` matches `#ffffff`. */
export function sameColor(a: string, b: string): boolean {
  const pa = parseColor(a)
  const pb = parseColor(b)
  if (!pa || !pb) return false
  const ra = hsvToRgb(pa)
  const rb = hsvToRgb(pb)
  return (
    Math.round(ra.r) === Math.round(rb.r) &&
    Math.round(ra.g) === Math.round(rb.g) &&
    Math.round(ra.b) === Math.round(rb.b) &&
    Math.round(ra.a * 255) === Math.round(rb.a * 255)
  )
}

// Generated by scripts/registry/barrels.ts — run `pnpm regen`. Do not edit.
export * from './color-picker'
export * from './color'

@layer cascivo.component {
  .wrapper {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-3);
    inline-size: fit-content;
    font-family: var(--cascivo-font-sans);

    &[data-disabled] {
      opacity: 0.5;
      pointer-events: none;
    }

    &[data-size='sm'] {
      --cascivo-color-picker-area-size: 9rem;
    }

    &[data-size='md'] {
      --cascivo-color-picker-area-size: 12rem;
    }

    &[data-size='lg'] {
      --cascivo-color-picker-area-size: 16rem;
    }
  }

  .label {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-snug);
  }

  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .area {
    position: relative;
    inline-size: var(--cascivo-color-picker-area-size, 12rem);
    block-size: var(--cascivo-color-picker-area-size, 12rem);
    border-radius: var(--cascivo-radius-md);
    cursor: crosshair;
    touch-action: none;
    background-image:
      linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent);
    background-color: var(--cascivo-color-border);

    &:has(.axis:focus-visible) {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  /* Real range inputs carrying the two axes' slider semantics. Sized to the area and made
     transparent rather than `display: none`, because a hidden input is not focusable and the
     whole point is that the platform supplies arrows, Home/End and PageUp/PageDown. */
  .axis {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    margin: 0;
    opacity: 0;
    cursor: crosshair;
    appearance: none;
  }

  .thumb {
    position: absolute;
    inline-size: 0.875rem;
    block-size: 0.875rem;
    border-radius: var(--cascivo-radius-full);
    border: 2px solid var(--cascivo-color-surface);
    box-shadow: var(--cascivo-shadow-sm);
    transform: translate(-50%, -50%);
    pointer-events: none;
  }

  .sliders {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
  }

  .slider {
    appearance: none;
    inline-size: 100%;
    block-size: 0.75rem;
    border-radius: var(--cascivo-radius-full);
    cursor: pointer;

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &::-webkit-slider-thumb {
      appearance: none;
      inline-size: 1rem;
      block-size: 1rem;
      border-radius: var(--cascivo-radius-full);
      background-color: var(--cascivo-color-surface);
      border: 2px solid var(--cascivo-color-border-strong);
      box-shadow: var(--cascivo-shadow-sm);
    }

    &::-moz-range-thumb {
      inline-size: 1rem;
      block-size: 1rem;
      border-radius: var(--cascivo-radius-full);
      background-color: var(--cascivo-color-surface);
      border: 2px solid var(--cascivo-color-border-strong);
      box-shadow: var(--cascivo-shadow-sm);
    }
  }

  .hue {
    background-image: linear-gradient(
      to right,
      #f00 0%,
      #ff0 17%,
      #0f0 33%,
      #0ff 50%,
      #00f 67%,
      #f0f 83%,
      #f00 100%
    );
  }

  .alpha {
    background-color: #fff;
    background-image:
      linear-gradient(to right, transparent, var(--cascivo-color-picker-alpha-to, #000)),
      conic-gradient(#0000 0.25turn, #ccc 0 0.5turn, #0000 0 0.75turn, #ccc 0);
    background-size:
      100% 100%,
      0.5rem 0.5rem;
  }

  .presets {
    display: flex;
    flex-wrap: wrap;
    gap: var(--cascivo-space-2);
  }

  .preset {
    inline-size: 1.5rem;
    block-size: 1.5rem;
    border-radius: var(--cascivo-radius-sm);
    border: 1px solid var(--cascivo-color-border);
    cursor: pointer;
    padding: 0;

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &[aria-pressed='true'] {
      outline: 2px solid var(--cascivo-color-accent);
      outline-offset: 2px;
    }
  }

  .row {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
  }

  .preview {
    inline-size: 1.75rem;
    block-size: 1.75rem;
    border-radius: var(--cascivo-radius-sm);
    border: 1px solid var(--cascivo-color-border);
    flex-shrink: 0;
  }

  .hex {
    flex: 1;
    min-inline-size: 0;
    font-family: var(--cascivo-font-mono);
    font-size: var(--cascivo-text-sm);
    padding-block: var(--cascivo-space-1);
    padding-inline: var(--cascivo-space-2);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .eyedropper {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.75rem;
    block-size: 1.75rem;
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    flex-shrink: 0;

    &:hover {
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  /* Coarse pointers get the 44px effective target the repo mandates; the swatches, the
     eyedropper and the two tracks were all well under it and had no block at all. */
  @media (pointer: coarse) {
    .preset,
    .eyedropper,
    .preview {
      min-inline-size: var(--cascivo-target-min-coarse, 2.75rem);
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }

    .slider {
      block-size: 1.5rem;
    }

    .hex {
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .thumb,
  .preset,
  .eyedropper {
    transition-duration: 1ms;
  }
}

@media (forced-colors: active) {
  .area:has(.axis:focus-visible),
  .preset:focus-visible,
  .eyedropper:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}
